files.content:
/* The surface clips every row, so revealed actions never spill past its rounded corners. It hides once the last row has left. */
.surface { overflow: hidden; border: 1px solid var(--border); border-radius: var(--radius-panel); background: var(--surface); transition: border-color var(--duration-standard) var(--ease-standard), background-color var(--duration-standard) var(--ease-standard); }
/* When the last row is on its way out, the frame fades with it instead of leaving a hairline behind. */
.surface:not(:has(> .list > .row:not([data-removing]))) { border-color: transparent; background-color: transparent; }
.surface:has(> .list:empty) { display: none; }
/* Pulled down one pixel so the last separator tucks under the frame, instead of toggling with :last-child while rows leave. */
.list { margin: 0 0 -1px; padding: 0; list-style: none; }
.list:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: -2px; }
.row { position: relative; isolation: isolate; overflow: hidden; }
/* The content follows the finger by transform only; vertical pans stay with the page. */
.content { position: relative; z-index: 10; display: flex; min-height: 64px; align-items: center; gap: var(--space-2); padding: var(--space-3) var(--space-2) var(--space-3) var(--space-4); background: var(--surface); touch-action: pan-y; user-select: none; -webkit-user-select: none; -webkit-touch-callout: none; }
.content::after { position: absolute; right: 0; bottom: 0; left: var(--swipe-actions-inset, var(--space-4)); height: 1px; background: var(--border); content: ""; pointer-events: none; }
.content img { -webkit-user-drag: none; }
.body { min-width: 0; flex: 1 1 auto; }
.more { display: grid; width: 32px; height: 32px; flex: none; place-items: center; border: 0; border-radius: calc(var(--radius-control) - 6px); background: transparent; color: var(--text-muted); cursor: pointer; -webkit-tap-highlight-color: transparent; transition: color var(--duration-fast) var(--ease-standard), background-color var(--duration-fast) var(--ease-standard); }
/* The button anchors a menu, so a press answers with colour, never scale. */
.more:active, .more[data-state="open"] { background: var(--surface-muted); color: var(--foreground); }
.more:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 0; }
@media (hover: hover) and (pointer: fine) {
  .content { cursor: grab; }
  .more:hover { background: var(--surface-muted); color: var(--foreground); }
}
.row[data-dragging] .content { cursor: grabbing; }
.row[data-dragging] .more { background: transparent; color: var(--text-muted); }

/* Each action spans the full row from the edge it hides behind and slides in by transform. Outer actions stack above inner ones. */
.layer { position: absolute; top: 0; bottom: 0; width: 100%; padding: 0; border: 0; background: color-mix(in oklch, var(--foreground) 20%, var(--surface)); color: var(--foreground); font: inherit; cursor: pointer; -webkit-tap-highlight-color: transparent; }
.layer[data-side="trailing"] { left: 100%; }
.layer[data-side="leading"] { right: 100%; }
.layer[data-tone="accent"] { background: var(--accent); color: var(--accent-foreground); }
.layer[data-tone="danger"] { background: var(--danger); color: var(--background); }
.layer:focus { outline: none; }
.anchor { position: absolute; top: 0; bottom: 0; width: 0; }
.layer[data-side="trailing"] .anchor { left: 0; }
.layer[data-side="leading"] .anchor { right: 0; }
.glyph { position: absolute; top: 0; bottom: 0; left: calc(var(--swipe-action-width) / -2); display: flex; width: var(--swipe-action-width); flex-direction: column; align-items: center; justify-content: center; gap: 3px; }
.icon { display: grid; place-items: center; }
.icon svg { width: 20px; height: 20px; }
.label { font-size: var(--text-xs); font-weight: 500; letter-spacing: var(--tracking-body); line-height: 1.2; white-space: nowrap; }

/* The menu grows from its trigger, matching the library dropdown. */
.menu { --menu-x: 0px; --menu-y: -5px; position: relative; z-index: 60; min-width: 11rem; padding: 5px; border: 1px solid var(--border); border-radius: var(--radius-panel); background: var(--surface-raised); box-shadow: var(--shadow-floating); transform-origin: var(--radix-dropdown-menu-content-transform-origin); }
.menu[data-side="top"] { --menu-y: 5px; }
.menu[data-state="open"] { animation: menu-fade-in var(--duration-fast) var(--ease-enter) both, menu-rise-in var(--duration-spring) var(--ease-spring) both; }
.menu[data-state="closed"] { animation: menu-out 130ms var(--ease-standard) both; }
.menu[data-state="open"] .item { animation: menu-item-in var(--duration-standard) var(--ease-enter) both; animation-delay: calc(min(var(--i, 0), 4) * 35ms); }
.item { position: relative; display: flex; min-height: 36px; align-items: center; gap: 10px; padding: 0 11px; border-radius: calc(var(--radius-panel) - 6px); color: var(--foreground); font-size: var(--text-sm); cursor: pointer; outline: none; transition: background-color var(--duration-instant) var(--ease-standard); }
.item[data-highlighted] { background: var(--surface-muted); }
.item[data-tone="danger"] { color: var(--danger); }
.item[data-tone="danger"][data-highlighted] { background: color-mix(in oklch, var(--danger) 8%, var(--surface-raised)); }
.itemIcon { display: inline-flex; width: 17px; color: var(--text-secondary); }
.itemIcon svg { width: 16px; height: 16px; }
.item[data-tone="danger"] .itemIcon { color: var(--danger); }
@keyframes menu-fade-in { from { opacity: 0; } }
@keyframes menu-rise-in { from { transform: translate(var(--menu-x), var(--menu-y)) scale(.97); } }
@keyframes menu-out { to { opacity: 0; transform: translate(calc(var(--menu-x) * .5), calc(var(--menu-y) * .5)) scale(.985); } }
@keyframes menu-item-in { from { opacity: 0; transform: translate(calc(var(--menu-x) * .4), calc(var(--menu-y) * .4)); } }
@keyframes menu-fade-out { to { opacity: 0; } }
@media (prefers-reduced-motion: reduce) {
  .surface, .more, .item { transition: none; }
  .menu[data-state="open"] { animation: menu-fade-in var(--duration-instant) linear both; }
  .menu[data-state="closed"] { animation: menu-fade-out 100ms linear both; }
  .menu[data-state="open"] .item { animation: none; }
}
